UPDATE digital_qa_ppt_finding SET first_feedback_notified_at=#{sentAt}, feedback_deadline_at=#{deadline}
WHERE first_feedback_notified_at IS NULL AND status='PENDING_FEEDBACK' AND id IN
#{id}

