SELECT config_id,daily,start_minute,end_minute FROM digital_qa_ppt_reminder_window WHERE config_id IN
#{id}
ORDER BY config_id,start_minute,end_minute

mapper.insert:
INSERT INTO digital_qa_ppt_feedback_notice(version_id,finding_id,recipient,kind,subject,body,assignment_revision,notified_at)
SELECT #{notice.versionId},#{notice.findingId},#{notice.recipient},#{notice.kind},#{subject},#{body},#{notice.assignmentRevision},
       COALESCE(#{notifiedAt,jdbcType=TIMESTAMP}, CURRENT_TIMESTAMP)
WHERE NOT EXISTS (
    SELECT 1 FROM digital_qa_ppt_feedback_notice
    WHERE version_id=#{notice.versionId} AND finding_id=#{notice.findingId}
      AND recipient=#{notice.recipient} AND kind=#{notice.kind} AND assignment_revision=#{notice.assignmentRevision}
)
AND (#{notice.kind} <> 'PENDING' OR EXISTS (
    SELECT 1 FROM digital_qa_ppt_finding
    WHERE id=#{notice.findingId} AND status='PENDING_FEEDBACK' AND assignment_revision=#{notice.assignmentRevision}
      AND EXISTS (SELECT 1 FROM digital_qa_ppt_finding_recipient h
                  WHERE h.finding_id=#{notice.findingId} AND h.user_id=#{notice.recipient})
    FOR UPDATE
))

mapper.select:
SELECT to_users,cc_users,sent_at FROM digital_qa_ppt_mail_record
WHERE version_id=#{versionId} AND department=#{department} AND subject=#{subject}
  AND status='SENT' AND sent_at IS NOT NULL

mapper.sql:
FROM digital_qa_ppt_keyword_config WHERE kind=#{kind}

    AND (POSITION(#{keyword} IN name)>0
    OR POSITION(#{keyword} IN target)>0)

AND target=#{target}

mapper.select:
SELECT latest.id AS version_id, latest.version_no, CASE WHEN latest.id=original.id THEN f.id ELSE ( SELECT CASE WHEN COUNT(CASE WHEN m.chapter=f.chapter THEN 1 END)=1 THEN MAX(CASE WHEN m.chapter=f.chapter AND (EXISTS (SELECT 1 FROM digital_qa_ppt_finding_recipient h WHERE h.finding_id=m.id AND h.user_id=#{user}) OR #{admin} OR latest.uploaded_by=#{user}) THEN m.id END) WHEN COUNT(*)=1 THEN MAX(CASE WHEN EXISTS (SELECT 1 FROM digital_qa_ppt_finding_recipient h WHERE h.finding_id=m.id AND h.user_id=#{user}) OR #{admin} OR latest.uploaded_by=#{user} THEN m.id END) END FROM digital_qa_ppt_finding m WHERE m.version_id=latest.id AND m.status <> 'DELETED' AND (f.feedback_department IS NULL OR m.feedback_department=f.feedback_department) AND length() > 0 AND =
) END AS finding_id, (latest.id=original.id OR f.id IS NULL OR EXISTS ( SELECT 1 FROM digital_qa_ppt_slide s WHERE s.version_id=latest.id AND length() > 0 AND =
)) AS title_present FROM digital_qa_ppt_material_version original JOIN digital_qa_ppt_material_version latest ON latest.batch_id=original.batch_id AND latest.status='ANALYZED' LEFT JOIN digital_qa_ppt_finding f ON f.id=#{finding,jdbcType=BIGINT} AND f.version_id=original.id AND f.status <> 'DELETED' WHERE original.id=#{version} AND (#{finding,jdbcType=BIGINT} IS NULL OR f.id IS NOT NULL) AND (latest.id=original.id OR NOT EXISTS ( SELECT 1 FROM digital_qa_ppt_assignment_change change WHERE change.finding_id=f.id )) AND (#{finding,jdbcType=BIGINT} IS NULL OR #{admin} OR original.uploaded_by=#{user} OR EXISTS (SELECT 1 FROM digital_qa_ppt_finding_recipient h WHERE h.finding_id=f.id AND h.user_id=#{user})) ORDER BY latest.version_no DESC LIMIT 1

SELECT EXISTS (
    SELECT 1 FROM digital_qa_ppt_finding f JOIN digital_qa_ppt_slide s ON s.id=f.slide_id
    WHERE f.version_id=#{version} AND f.status <> 'DELETED' AND s.page_no=#{page} AND f.id <> #{exclude}
        AND (f.feedback_department=#{department} OR
             (f.feedback_department IS NULL AND f.auto_departments=#{departments}))
)

mapper.insert:
INSERT INTO digital_qa_ppt_finding_feedback(finding_id,judgement,adjusted_departments,explanation,user_id,assignment_revision)
SELECT id,#{judgement},#{departments},#{explanation},#{user},assignment_revision
FROM digital_qa_ppt_finding WHERE id=#{id}

mapper.select:
SELECT f.id FROM digital_qa_ppt_finding f
JOIN digital_qa_ppt_finding_recipient h ON h.finding_id=f.id
WHERE f.version_id=#{version} AND f.status <> 'DELETED' AND h.user_id=#{user}

SELECT target FROM digital_qa_ppt_keyword_config
WHERE kind='department' AND id=#{id}

FOR UPDATE

mapper.insert:
INSERT INTO digital_qa_ppt_report_notification (department, recipients_to, recipients_cc)
VALUES (#{department}, #{toJson}, #{ccJson})
ON DUPLICATE KEY UPDATE recipients_to = #{toJson}, recipients_cc = #{ccJson}
